const PRIV = 'Обезличьте: ФИО, ID, названия организаций и пути замените вымышленными. Можно ли отправлять рабочий код во внешний сервис, решает работодатель и ИТ.'
const ZUP = '**Учебные файлы.** Отчёт «Штатные сотрудники» из 1С:ЗУП — это .xls (формат BIFF8), лист «Лист_1», шапка отчёта занимает 9 строк, заголовки таблицы — в строке 10; название подразделения стоит отдельной строкой в колонке A (ставки в ней нет); колонки «Сотрудник» и «Количество ставок» в разных файлах стоят на разных местах. Учебные .xls в этой структуре лежат в архиве chislennost-power-query.zip (папка vygruzki/2026-10: 11 отчётов вымышленных организаций, 50 строк; там же списки, готовые запросы M и README с эталонами — проект EXT02). Простой учебной папкой с ID для первых шагов служит архив chislennost-papka-vygruzok.zip (папка 2026-10: alfa, beta, gamma — 10 строк, 7 ID).'

// ─── помощники ────────────────────────────────────────────────────────────
/** Шаги: по одному действию на строку. */
const st = (...a: string[]) => a.map((t, i) => `**Шаг ${i + 1}.** ${t}`).join('\n')
/** Строка кода M и её объяснение простыми словами. */
const C = (line: string, why: string) => '`' + line + '` — ' + why
const code = (...rows: Array<[string, string]>) => rows.map(([l, w]) => C(l, w)).join('\n')

const RAW: Array<{ key: string; after: string; text: string; screen: ReconScreen }> = []
const fig = (key: string, after: string, text: string, screen: ReconScreen) => { RAW.push({ key, after, text, screen }) }
const XL = 'Excel для Windows (Microsoft 365)'
const PQ = 'Excel для Windows · Редактор Power Query'
const gridOf = (cols: string[], rows: string[][], hi?: [number, number]) => ({ headers: cols, rows, hi })
const RIB = ['Файл', 'Главная', 'Преобразование', 'Добавление столбца', 'Вид']

const S = (id: string, title: string, url: string, status: 'opened' | 'not-checked', note?: string, checked = '2026-11-27', publisher = 'Microsoft Learn'): AccSource =>
  ({ id, title, url, publisher, kind: 'vendor-doc', checked, status, ...(note ? { note } : {}) })
const URLNC = 'Адрес отвечает (HTTP 200), текст страницы автор не сверял — подпись и поведение функции не утверждаются сверх общеизвестного описания; проверьте в справке'
const M = (id: string, fn: string, slug: string, status: 'opened' | 'not-checked' = 'not-checked') =>
  S(id, fn, `https://learn.microsoft.com/en-us/powerquery-m/${slug}`, status, status === 'opened' ? undefined : URLNC)

