const ALL: AccLesson[] = [L1, L2, L3, L4, L5, L6, L7, L8, L9, L10, L11, L12, L13, L14]

// Схемы: подписи «шаг N из M» считаем автоматически по числу кадров урока.
const FIGS: Record<string, LessonFigure[]> = {}
{
  const total: Record<string, number> = {}
  RAW.forEach(r => { total[r.key] = (total[r.key] ?? 0) + 1 })
  const seen: Record<string, number> = {}
  RAW.forEach(r => {
    seen[r.key] = (seen[r.key] ?? 0) + 1
    ;(FIGS[r.key] ??= []).push({ after: r.after, caption: `Учебная реконструкция: кадр ${seen[r.key]} из ${total[r.key]} — ${r.text}.`, src: reconScreen(r.screen) })
  })
}

